<?php require '../includes/config.php';require '../includes/funciones.php';if(!esAdmin()){header('Location: ../login.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare("UPDATE citas SET estado=?,observaciones=? WHERE id=?");$st->execute([$_POST['estado'],trim($_POST['observaciones']??''),(int)$_POST['id']]);header('Location: citas.php');exit;}$q=$pdo->query("SELECT c.*,m.nombre mascota,s.nombre servicio,uc.nombre cliente,uv.nombre veterinario FROM citas c JOIN mascotas m ON m.id=c.mascota_id JOIN servicios s ON s.id=c.servicio_id JOIN usuarios uc ON uc.id=c.usuario_id JOIN veterinarios v ON v.id=c.veterinario_id JOIN usuarios uv ON uv.id=v.usuario_id ORDER BY c.fecha_cita DESC,c.hora_cita DESC")->fetchAll();$titulo='Admin citas';require '../includes/header.php';?><h1>Gestión de citas</h1><div class="card" style="overflow:auto"><table><tr><th>Fecha</th><th>Cliente</th><th>Mascota</th><th>Servicio</th><th>Veterinario</th><th>Estado</th><th>Actualizar</th></tr><?php foreach($q as $c):?><tr><td><?=e($c['fecha_cita'])?> <?=substr($c['hora_cita'],0,5)?></td><td><?=e($c['cliente'])?></td><td><?=e($c['mascota'])?></td><td><?=e($c['servicio'])?></td><td><?=e($c['veterinario'])?></td><td><?=e($c['estado'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$c['id']?>"><select name="estado"><option>pendiente</option><option>confirmada</option><option>reprogramada</option><option>en_atencion</option><option>finalizada</option><option>cancelada</option><option>no_asistio</option></select><input name="observaciones" placeholder="Observación"><button class="btn">Guardar</button></form></td></tr><?php endforeach;?></table></div><?php require '../includes/footer.php';?>
